<template><view class="page"><view class="filter"><picker mode="date" :value="day" @change="changeDay"><view>{{day}}⌄</view></picker><text @click="load">刷新</text></view><view v-if="report" class="grid"><view v-for="item in metrics" :key="item.label" class="metric"><text class="value">{{item.value}}</text><text class="label">{{item.label}}</text></view></view><view v-if="report" class="section"><text class="title">闭环情况</text><view class="bar"><view class="bar__confirmed" :style="{width:confirmedRate+'%'}"/></view><text class="desc">已复核 {{reviewedCount}} 项，待复核 {{report.pendingCount}} 项，确认异常 {{report.confirmedCount}} 项，误报 {{report.falsePositiveCount}} 项。</text></view><view v-if="loading" class="state">正在生成巡检报告…</view></view></template>
<script setup lang="ts">
import{computed,ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{getInspectionReport,type InspectionReport}from'@/api/inspection';import{showRequestError}from'@/utils/request';import{useAuthStore}from'@/stores/auth';const auth=useAuthStore(),day=ref(new Date().toISOString().slice(0,10)),report=ref<InspectionReport>(),loading=ref(false);const metrics=computed(()=>report.value?[{label:'巡检任务',value:report.value.taskCount},{label:'完成任务',value:report.value.completedCount},{label:'发现异常',value:report.value.abnormalCount},{label:'待复核',value:report.value.pendingCount}]:[]);const reviewedCount=computed(()=>report.value?report.value.confirmedCount+report.value.falsePositiveCount:0);const confirmedRate=computed(()=>report.value?.abnormalCount?Math.round(reviewedCount.value/report.value.abnormalCount*100):0);async function load(){loading.value=true;try{report.value=await getInspectionReport(day.value)}catch(e){showRequestError(e)}finally{loading.value=false}}function changeDay(e:any){day.value=e.detail.value;load()}onShow(()=>{if(auth.requireAuth())load()})
</script><style scoped>.page{min-height:100vh;padding:24rpx;box-sizing:border-box}.filter{display:flex;justify-content:space-between;padding:24rpx 28rpx;background:#fff;border-radius:20rpx;font-size:25rpx}.filter>text{color:#2368f2}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16rpx;margin-top:20rpx}.metric{padding:32rpx;background:#fff;border-radius:22rpx}.value,.label{display:block}.value{font-size:42rpx;font-weight:700}.label{margin-top:8rpx;color:#8992a6;font-size:23rpx}.section{margin-top:20rpx;padding:30rpx;background:#fff;border-radius:22rpx}.title{font-size:29rpx;font-weight:600}.bar{height:18rpx;margin-top:28rpx;background:#edf0f5;border-radius:999rpx;overflow:hidden}.bar__confirmed{height:100%;background:#2368f2;border-radius:999rpx}.desc{display:block;margin-top:18rpx;color:#667085;font-size:24rpx;line-height:1.6}.state{padding:100rpx;text-align:center;color:#8992a6}</style>
